  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "CLR457, a close structural analog containing the same CF3-aminopyridine and morpholine-substituted azine motif, showed a brain/plasma AUC ratio of 0.07, indicating minimal CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A related aminopyridine/morpholine-fused compound showed minimal total brain exposure (AUC0-8 = 104 ng·h/g) after oral dosing in rats, supporting poor CNS access for this polar morpholine-azine class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A CF3-containing morpholine amide analog had a brain unbound/plasma unbound ratio of 0.08, indicating poor brain penetration despite structural similarity to the query's polar morpholine and CF3 elements.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "A morpholine-substituted heteroaryl radioligand reached a whole-brain SUV of 2.8 within 5 minutes in rats, demonstrating that some morpholine-azine compounds can be brain penetrant.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "GNE-7915, a brain-penetrant CF3/morpholine-containing compound, achieved a CSF/plasma unbound ratio of 0.6 in rats, showing that related polar morpholine amides can still access the CNS.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's bis-morpholino triazine core with an amino-CF3-pyridine substituent is most closely mirrored by CLR457, which had very poor brain penetration (AUC ratio 0.07). Multiple related polar morpholine/CF3/aminopyridine analogs also showed poor CNS exposure, while the good-penetration examples are less structurally direct and generally contain only one morpholine or a different core. Overall, the balance favors inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain PK, CSF, or efflux measurement exists for the exact query molecule.",
    "The closest analog evidence is a single tissue/plasma AUC ratio from CLR457; unbound brain or CSF data are absent.",
    "No P-gp/BCRP transporter data are available for the bis-morpholino triazine scaffold.",
    "The query's two morpholine groups likely increase TPSA and efflux liability, but this is inferred rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

